from collections import deque

def transform(grid):
 h,w=len(grid),len(grid[0]); seen=set(); comps=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c] and (r,c) not in seen:
    color=grid[r][c]; q=[(r,c)]; seen.add((r,c)); comp=[]
    while q:
     x,y=q.pop(); comp.append((x,y,color))
     for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
      if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==color:
       seen.add((a,b)); q.append((a,b))
    comps.append(comp)
 comps.sort(key=lambda co:max(c for r,c,v in co), reverse=True)
 placed=set(); moved=[]
 for comp in comps:
  cells={(r,c) for r,c,v in comp}; d=0
  while all(c+d+1<w and (r,c+d+1) not in placed and (r,c+d+1) not in cells for r,c,v in comp): d+=1
  new=[(r,c+d,v) for r,c,v in comp]; moved.append(new); placed.update((r,c) for r,c,v in new)
 out=[[0]*w for _ in range(h)]
 for comp in moved:
  for r,c,v in comp: out[r][c]=v
 return out

